define({"topics":[{"title":"Installing operator documentation (online help)","shortdesc":"<p class=\"shortdesc\"> Load the operator manuals onto the host computer so customers can have access to the manuals any time they are using the system.<\/p>","href":"t_InstallingOperatorDocumentation.html","attributes":{"data-id":"id_2001527"},"menu":{"hasChildren":false},"tocID":"id_2001527-d46e31018","topics":[]},{"title":"Installing host system software","shortdesc":"<p class=\"shortdesc\">This quick start guide provides an overview of the procedures required to load host system software. Refer to the tasks included within this procedure for detailed information.<\/p>","href":"r_InstallingHostSystemSoftware.html","attributes":{"data-id":"id_2003115"},"menu":{"hasChildren":true},"tocID":"id_2003115-d46e31121","next":"id_2003115-d46e31121"},{"title":"Installing service packs","shortdesc":"<p class=\"shortdesc\">When GE releases new software versions, it may be necessary to install updates to a host PC. <\/p>","href":"t_InstallingServicePacks.html","attributes":{"data-id":"id_2002881"},"menu":{"hasChildren":true},"tocID":"id_2002881-d46e36464","next":"id_2002881-d46e36464"},{"title":"Installing updates from Remote Software Download (RSD) for <span class=\"ph\">software version 30<\/span> through software version 30.1","shortdesc":"<p class=\"shortdesc\">Remote Software Download (RSD) is an installer application that helps to install new updates from service packs whenever they are released and pushed from the GE HealthCare back office.<\/p>","href":"t_InstallingUpdatesFromRSD_29.1_To_30.1_2.html","attributes":{"data-id":"id_2029979"},"menu":{"hasChildren":false},"tocID":"id_2029979-d46e37079","topics":[]}]});